#!/bin/bash
# Downloads a thumbnail for every catalogue target into thumbs/ (run from the Sky-Watch folder: bash tools/get-thumbs.sh).
# Safe to re-run: files already downloaded are skipped.
cd "$(dirname "$0")/.." || exit 1
mkdir -p thumbs
fail=0
get() { [ -s "$2" ] && return 0; for i in 1 2 3 4; do curl -fsSL --max-time 60 -o "$2.tmp" "$1" && [ -s "$2.tmp" ] && mv "$2.tmp" "$2" && echo "ok  $2" && return 0; sleep 3; done; rm -f "$2.tmp"; echo "FAILED $2"; fail=$((fail+1)); }
